{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver korrekt journalkravet og kravet om beskrivelse af den varige funktionsnedsættelse. Det angiver dog epikrise eller afslutningsbrev som en del af det faste minimumskrav ('skal som minimum indeholde'). Kilden siger, at dokumentationen 'som udgangspunkt' vil indeholde det. Ekspertrubrikken opregner netop 'epikrise eller afslutningsbrev er altid et absolut krav' som en væsentlig fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Journalmateriale og beskrivelse af den varige funktionsnedsættelse er med. Det tredje kritiske element er, at epikrise eller afslutningsbrev som udgangspunkt indgår ved afsluttet behandling. Det er gengivet som et ufravigeligt krav, så elementet er ikke kommunikeret ækvivalent."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken lægelig dokumentation en ansøgning skal indeholde, når behandlingen er afsluttet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret henviser hverken til en bestemmelse (fx SU-bekendtgørelsen § 37) eller til vejledningen. Ingen identificerbar kilde er angivet."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde støtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en betingelse uden støtte: at epikrise eller afslutningsbrev er en del af minimumskravet. Kilderne (§ 37, stk. 3 og vejledningen afsnit 4.1) kræver kun journaler som minimum og nævner epikrise 'som udgangspunkt'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdet 'som udgangspunkt' ved epikrise/afslutningsbrev er udeladt. Svaret nævner heller ikke, at dokumentets titel ikke i sig selv afgør tilstrækkeligheden."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er kort og internt konsistent. Der er ingen modstridende trin, og konklusionen følger af den opstillede liste, selv om listen er unøjagtig."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Skal som minimum' omfatter også epikrise/afslutningsbrev og gør dermed et 'som udgangspunkt' til et absolut krav. Vejledningens 'afviser Udbetaling Danmark' er desuden gengivet som 'kan ... afvise'."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "partial",
      "reason": "Svaret behandler situationen med afsluttet behandling og nævner epikrise eller afslutningsbrev. Det udelader 'som udgangspunkt' og gør det til et ufravigeligt minimumskrav."
    },
    "A32": {
      "label": "partial",
      "reason": "Svaret angiver, at dokumentationen skal indeholde epikrise eller afslutningsbrev. Det er korrekt i retning, men uden forbeholdet 'som udgangspunkt'."
    }
  },
  "overall_notes": "Svaret rammer journalkravet og kravet om beskrivelse af den varige funktionsnedsættelse korrekt. Hovedfejlen er, at epikrise/afslutningsbrev præsenteres som et absolut minimumskrav i stedet for 'som udgangspunkt', hvilket er en udpeget væsentlig fejl i rubrikken. Svaret angiver ingen kilde, derfor C04 not_met og C05/C06 not_assessable."
}

